mapper.select:
select c.id, c.knowledge_base_id, c.document_id, c.content, d.title as document_title, d.file_name, 1 - (c.embedding <=> #{queryVector}::vector) as similarity from document_chunk c join knowledge_document d on d.id = c.document_id and d.deleted = false where c.deleted = false and c.embedding is not null
and c.knowledge_base_id in
#{kbId}
order by c.embedding <=> #{queryVector}::vector asc limit #{topK}
